import random, subprocess, sys, tempfile
from pathlib import Path
REFERENCE='# External reference: statistics page /practice/28969/\n# Accepted submission: 52842137\n# Source: http://cs101.openjudge.cn/practice/solution/52842137/\n# License: not declared on the submission page; no license is inferred.\n\n\ndef dec(s):\n    n=len(s)\n    if n==0:\n        return ""\n    if n==1:\n        return s\n    mid=(1+n)//2\n    sl=dec(s[1:mid])\n    sr=dec(s[mid::])\n    return sl+s[0]+sr\n\ndef main():\n    s=input()\n    print(dec(s))\n\n    return \n\n\n\nif __name__=="__main__":\n    main()'
SAMPLE='123456789\n'
EXTRA_CASE='\n'
GENERATOR_NAME='g28969'
def g28969(r):
    return "".join(r.choice("0123456789") for _ in range(r.randint(1, 300))) + "\n"

def run(text):
    with tempfile.TemporaryDirectory(prefix='producecase-') as d:
        p=Path(d)/'main.py'; p.write_text(REFERENCE)
        x=subprocess.run([sys.executable,str(p)],input=text,text=True,capture_output=True,timeout=120)
        if x.returncode: raise SystemExit(x.stderr)
        return x.stdout
def main():
    d=Path('data'); d.mkdir(exist_ok=True)
    cases=[SAMPLE]+([EXTRA_CASE] if EXTRA_CASE else [])+[globals()[GENERATOR_NAME](random.Random(s)) for s in range(1,21)]
    for i,c in enumerate(cases): (d/f'{i}.in').write_text(c); (d/f'{i}.out').write_text(run(c))
if __name__=='__main__': main()
